css:
.print-heading {
    text-align: center;
    margin-bottom: 20px;
}

.print-heading h2 {
    margin: 0;
}

.print-heading .sub-heading {
    font-size: 14px;
    color: gray;
}

table {
    width: 100%;
    border-collapse: collapse;
    margin-top: 10px;
    margin-bottom: 20px;
}

table th, table td {
    padding: 5px;
}

table th {
    text-align: center;
    vertical-align: middle;
}

table td {
    text-align: left;
    vertical-align: middle;
}

table .barcode-cell {
    text-align: center;
    vertical-align: middle;
}

img.barcode {
    width: 200px;
    height: 70px;
}
